const inputs={dec:document.getElementById("base-dec"),bin:document.getElementById("base-bin"),hex:document.getElementById("base-hex"),oct:document.getElementById("base-oct")};function updateBases(e,t){if(e===""){Object.values(inputs).forEach(e=>e.value="");return}try{const n=parseInt(e,t);if(isNaN(n))return;t!==2&&(inputs.bin.value=n.toString(2)),t!==8&&(inputs.oct.value=n.toString(8)),t!==10&&(inputs.dec.value=n.toString(10)),t!==16&&(inputs.hex.value=n.toString(16).toUpperCase())}catch{console.error("Erro na conversão de base.")}}inputs.dec.addEventListener("input",e=>updateBases(e.target.value,10)),inputs.bin.addEventListener("input",e=>updateBases(e.target.value,2)),inputs.hex.addEventListener("input",e=>updateBases(e.target.value,16)),inputs.oct.addEventListener("input",e=>updateBases(e.target.value,8))